style.css:
/* Dusty Pink and Dark Theme for YouTube */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("youtube.com") {
/* General Background */
  body {
    background-color: #2a2a2a !important;
    color: #f7d9d9 !important;
  }

  #container, #masthead-container, #content {
    background-color: #2a2a2a !important;
    color: #f7d9d9 !important;
  }

  /* Top Navigation Bar */
  #masthead {
    background-color: #3c3c3c !important;
    border-bottom: 1px solid #f7d9d9 !important;
  }

  /* Sidebar and Menus */
  #guide {
    background-color: #3c3c3c !important;
    color: #f7d9d9 !important;
  }

  ytd-mini-guide-entry-renderer, ytd-guide-entry-renderer {
    color: #f7d9d9 !important;
  }

  /* Video Thumbnails */
  ytd-thumbnail, ytd-thumbnail-overlay {
    background-color: #3c3c3c !important;
  }

  /* Video Titles */
  a.yt-simple-endpoint.style-scope.ytd-video-renderer {
    color: #f7d9d9 !important;
  }

  /* Buttons and Links */
  a, .yt-simple-endpoint, .style-scope.ytd-button-renderer {
    color: #f7d9d9 !important;
  }

  /* Dusty Pink Highlights */
  ytd-guide-entry-renderer:hover, 
  ytd-mini-guide-entry-renderer:hover, 
  .yt-simple-endpoint.style-scope.ytd-guide-entry-renderer:hover {
    background-color: #d6a8a8 !important;
    color: #2a2a2a !important;
  }

  .style-scope.ytd-searchbox:hover,
  .style-scope.ytd-searchbox:focus-within {
    border-color: #d6a8a8 !important;
  }

  /* Player Area */
  .html5-video-container, 
  #movie_player {
    background-color: #2a2a2a !important;
  }

  /* Comments Section */
  #comments {
    background-color: #2a2a2a !important;
    color: #f7d9d9 !important;
  }

  /* Dusty Pink Buttons */
  .ytp-chrome-controls {
    background-color: #3c3c3c !important;
  }

  .ytp-chrome-controls .ytp-button:hover {
    color: #d6a8a8 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
    background-color: #2a2a2a;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #d6a8a8;
    border-radius: 4px;
  }

  /* Miscellaneous */
  ytd-topbar-logo-renderer {
    filter: brightness(0.8);
  }
}
